'use strict';
(() => {
const D=LocHire,main=document.querySelector('main'),dialog=document.querySelector('dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'₦'+Number(v||0).toLocaleString('en-NG',{maximumFractionDigits:2});
const at=v=>v?new Date(v).toLocaleString('en-NG',{timeZone:'Africa/Lagos',dateStyle:'medium',timeStyle:'short'})+' WAT':'';
const icons={work:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m3-16a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-3-5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/>',arrow:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',star:'<path d="m12 3 2.8 5.7 6.3.9-4.6 4.5 1.1 6.3-5.6-3-5.6 3 1.1-6.3L3 9.6l6.2-.9Z"/>'};
Object.assign(icons,{settings:'<path d="m9 3-1 3-3 1 1 3-1 3 3 1 1 3h6l1-3 3-1-1-3 1-3-3-1-1-3Z"/><circle cx="12" cy="10" r="3"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18m-5 4h5v4h-5a2 2 0 0 1 0-4Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',moon:'<path d="M20 14A8 8 0 0 1 10 4a9 9 0 1 0 10 10Z"/>',device:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',filter:'<path d="M4 6h16M7 12h10m-7 6h4"/>',chevron:'<path d="m6 9 6 6 6-6"/>',more:'<path d="M4 6h16M4 12h16M4 18h16"/>'});
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.work}</svg>`;
const btn=(t,a,primary=false,attrs='')=>`<button type="button" class="button ${primary?'primary':'secondary'}" data-action="${a}" ${attrs}>${t}</button>`;
const field=(n,l,v='',type='text',attrs='')=>`<div class="field"><label for="f-${n}">${l}</label><input id="f-${n}" name="${n}" type="${type}" value="${esc(v)}" ${attrs}></div>`;
const textarea=(n,l,v='',required=true)=>`<div class="field"><label for="f-${n}">${l}</label><textarea id="f-${n}" name="${n}" maxlength="1500" ${required?'required':''}>${esc(v)}</textarea></div>`;
const optionText=t=>({'Hourly':'Every hour','Daily':'Every day','Monthly':'Every month','Per task':'For the whole job','Ongoing job':'Regular work','One-off task':'One job / task','Live-in':'Stay at the workplace','Live-out':'Go home after work','Either':'Either is fine','Not applicable':'Not needed','Household':'Home / family'}[t]||t);
const select=(n,l,options,v='')=>`<div class="field"><label for="f-${n}">${l}</label><select id="f-${n}" name="${n}">${options.map(x=>{const [k,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(k)}" ${String(k)===String(v)?'selected':''}>${esc(optionText(t))}</option>`;}).join('')}</select></div>`;
const check=(n,l,on=false)=>`<label class="check-field"><input name="${n}" type="checkbox" ${n==='adultConsent'?'required':''} ${on?'checked':''}><span>${l}</span></label>`;
const multi=(n,l,values,chosen=[])=>`<fieldset class="multi"><legend>${l}</legend>${values.map(v=>`<label><input name="${n}" type="checkbox" value="${v}" ${chosen.includes(v)?'checked':''}><span>${v}</span></label>`).join('')}</fieldset>`;
const errorBox=()=>'<p id="form-error" role="alert" tabindex="-1"></p>';
const head=(t,p,action='')=>`<section class="page-top"><div><div class="eyebrow">Local people. Everyday work.</div><h1>${esc(t)}</h1><p>${esc(p)}</p></div>${action}</section>`;
const empty=(t,p,a='')=>`<div class="empty"><span class="empty-icon">${icon('work')}</span><h3>${esc(t)}</h3><p>${esc(p)}</p>${a}</div>`;
const detail=items=>`<dl class="detail-grid">${items.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v||'Not specified')}</dd></div>`).join('')}</dl>`;
const badge=s=>`<span class="badge">${esc(s)}</span>`;
const disclosure=(key,title,body,note='',open=false)=>`<details class="disclosure" data-disclosure="${key}" ${open?'open':''}><summary><span>${esc(title)}${note?`<small>${esc(note)}</small>`:''}</span>${icon('chevron')}</summary><div class="disclosure-body">${body}</div></details>`;
const menuRow=(title,pageName,i='arrow',sub='')=>`<button data-page="${pageName}">${icon(i)}<span>${esc(title)}${sub?`<small>${esc(sub)}</small>`:''}</span>${icon('arrow')}</button>`;
const disclosures=new Map();
let state={workerMatches:[],user:null,worker:null,employer:null,workers:[],employers:[],openings:[],engagements:[],reviews:[],blocks:[],notifications:[],payments:[],reports:[]},config={};
let verificationMessage='',verificationNext=null,verifiedLinkUser='';
let lastHeartbeat=0;
let adminQuery='',adminVerified='',adminListPage=1,adminLoad=0;
let role=localStorage.getItem('lochire-role')==='employer'?'employer':'worker',page='home',routeId='',q='',category='',city='',minimum='',sort='recent',radius='',locationPoint=null,loading=true,networkError='',authMode='login',pending=null;
const own=()=>role==='worker'?state.worker:state.employer;
const person=id=>[...state.workers,...state.employers,state.worker,state.employer].find(p=>p?.id===id);
const engagement=id=>state.engagements.find(g=>g.id===id);
const actor=g=>g.workerId===state.worker?.id?g.workerId:g.employerId===state.employer?.id?g.employerId:null;
const rating=id=>{const r=state.reviews.filter(r=>r.target===id);return {count:r.length,average:r.length?r.reduce((s,r)=>s+r.rating,0)/r.length:0};};
const ratings=id=>{const r=rating(id);return `<p class="worker-rating">${icon('star')} ${r.count?r.average.toFixed(1)+' / 5 · '+r.count+' '+(r.count===1?'review':'reviews'):'No reviews yet'}</p>`;};
const rate=(p,job=false)=>p.quote||p.flexible?'Discuss a quote':(job?money(p.min)+' – '+money(p.max):money(p.pay))+' / '+({Hourly:'hour',Daily:'day',Monthly:'month','Per task':'task'}[p.basis]||'discuss');
const pidAttr=id=>`data-id="${esc(id)}"`;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),6000);}
function formError(t){const el=document.querySelector('#form-error');if(el){el.textContent=t;el.focus();}else toast(t);}
async function api(path,body){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{Accept:'application/json'}:{Accept:'application/json','Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(35000)});const d=await r.json().catch(()=>({error:'Unexpected service response.'}));if(!r.ok){const e=Error(d.error||'The request could not be completed.');e.status=r.status;throw e;}return d;}
const statePath=()=>locationPoint?'hiring/state?lat='+encodeURIComponent(locationPoint.lat)+'&lon='+encodeURIComponent(locationPoint.lon):'hiring/state';
let stateEpoch=0,authEpoch=0,refreshTask=null,authTransition=false;
function adoptState(data,restoreRole=false){if(state.user?.id!==data.user?.id){financeLoad++;}stateEpoch++;state=data;networkError='';if(restoreRole&&['worker','employer'].includes(data.user?.activeRole)){role=data.user.activeRole;localStorage.setItem('lochire-role',role);} }
async function refresh(draw=true){if(authTransition)return;const epoch=stateEpoch;const task=refreshTask?.epoch===epoch?refreshTask:{epoch,promise:api(statePath())};refreshTask=task;try{const data=await task.promise;if(epoch!==stateEpoch)return;state=data;heartbeat();networkError='';if(draw&&!dialog.open&&(!main.querySelector('form')||(page==='record'&&!main.querySelector('textarea')?.value.trim())))render();else navigation();}catch(e){if(epoch===stateEpoch){networkError='Could not refresh LocHire. '+e.message;navigation();}}finally{if(refreshTask===task)refreshTask=null;}}
async function change(path,body){const identity=authEpoch;stateEpoch++;const d=await api(path,body);if(identity!==authEpoch)return d;if(d.version>=4)adoptState(d);else await refresh(false);return d;}
function clearDiscoveryFilters(){q='';category='';city='';minimum='';sort='recent';radius='';}
function navigation(){const unread=state.notifications.filter(n=>!n.read_at).length;const tabs=[['discover',role==='worker'?'Find jobs':'Workers',role==='worker'?'search':'people'],['engagements','My work','work'],['notifications','Messages','mail'],['profile','My profile','user']];document.querySelector('#nav').innerHTML=tabs.map(([p,t,i])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${p==='notifications'&&unread?`<span class="nav-count" aria-label="${unread} unread updates">${Math.min(unread,99)}</span>`:''}</button>`).join('');document.querySelector('#role-button').innerHTML=(role==='worker'?'Find work':'Hire')+icon('chevron');const el=document.querySelector('#connection-status');el.hidden=!networkError;el.textContent=networkError;}
function mainMenu(){modal('Your menu','Choose what you want to do.',`<div class="settings-menu">${menuRow('Premium & payments','premium','star','Job access and nearby email alerts')}${menuRow('Settings','settings','settings','Appearance and preferences')}${menuRow(state.user?'My account':'Sign in / create account','account','user')}${role==='employer'?menuRow('Live worker matches','available','people','Available people for your openings')+menuRow('My job posts','openings','work'):''}${state.admin?menuRow('Admin dashboard','admin','shield','Users, growth and reports'):''}${menuRow('Help & support','help','shield')}</div>`);}
function restoreDisclosures(){main.querySelectorAll('[data-disclosure]').forEach(d=>{const key=page+'/'+routeId+'/'+d.dataset.disclosure;if(disclosures.has(key))d.open=disclosures.get(key);});}

function go(p,id=''){if(dialog.open)dialog.close();page=p;routeId=id;const hash=p+(id?'/'+encodeURIComponent(id):'');if(location.hash.slice(1)!==hash)location.hash=hash;render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
function modal(title,description,body){document.querySelector('#dialog-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" type="button" data-action="close" aria-label="Close">${icon('close')}</button></div><p class="modal-desc">${esc(description)}</p>${body}`;if(!dialog.open)dialog.showModal();}
function requireAccount(next){if(state.user){if(state.verificationRequired){verificationNext=next;go('check-email');return false;}return true;}pending=next;auth();return false;}
function requireProfile(next){if(!requireAccount(next))return false;if(own())return true;toast('Create your '+role+' profile first.');go('edit-profile');return false;}
function auth(mode='login'){authMode=mode;const create=mode==='register',forgot=mode==='forgot';modal(create?'Create your LocHire account':forgot?'Reset your password':'Welcome back',create?'You must be 18 or older. Use one account to find work or hire.':forgot?'Request a password reset email.':'Sign in to continue your hiring and conversations.',`<form id="auth-form">${create?field('name','Your name','','text','required maxlength="70" autocomplete="name"')+field('dateOfBirth','When were you born?','','date',`required min="1900-01-01" max="${D.adultBirthCutoff()}" autocomplete="bday" aria-describedby="age-help"`)+`<p id="age-help" class="caption age-note">LocHire is for people aged 18 and above. Your birth date is used for this check and is not shown on your profile.</p>`+field('phone','Nigerian phone number','','tel','required pattern="(0|\\+234)[0-9]{10}" autocomplete="tel"'):''}${field('email','Email address',forgot?state.user?.email||'':'','email','required maxlength="254" autocomplete="email"')}${!forgot?field('password',create?'Password (at least 10 characters)':'Password','','password',`required minlength="10" maxlength="200" autocomplete="${create?'new-password':'current-password'}"`):''}${create?check('adultConsent','I confirm that I am 18 or older.')+check('termsConsent','I agree to the <a href="#guidelines" target="_blank" rel="noopener">terms</a> and <a href="#privacy" target="_blank" rel="noopener">privacy notice</a>.'):''}${errorBox()}<p id="auth-status" class="form-status" role="status" hidden></p><button type="submit" class="button primary">${create?'Create account':forgot?'Request reset email':'Sign in'}</button><div class="auth-links">${btn(create?'I already have an account':'Create account',create?'auth-login':'auth-register')}${!forgot?btn('Forgot password?','auth-forgot'):btn('Back to sign in','auth-login')}</div></form>`);}
function render(){navigation();if(loading){main.innerHTML=empty('Loading LocHire','Connecting to saved profiles and openings.');return;}const pages={'join-worker':()=>joinPage('worker'),'join-hirer':()=>joinPage('employer'),password:passwordPage,'check-email':checkEmailPage,'email-verified':emailVerifiedPage,settings:settingsPage,home,discover,available:availablePage,profile:profilePage,'edit-profile':profileForm,openings:openingsPage,'edit-opening':openingForm,person:personPage,worker:personPage,employer:personPage,opening:openingPage,engagements:engagementsPage,record:recordPage,notifications:notificationsPage,messages:notificationsPage,wallet:walletPage,account:accountPage,help:helpPage,privacy:privacyPage,guidelines:termsPage,admin:adminPage,finance:financePage,premium:premiumPage,reset:resetPage,verify:verifyPage};if(state.verificationRequired&&['edit-profile','edit-opening'].includes(page)){checkEmailPage();}else (pages[page]||home)();restoreDisclosures();}
function joinPage(target){const worker=target==='worker';main.innerHTML=head(worker?'Find work near you.':'Find local help.','Join LocHire in three simple steps.')+`<section class="panel"><h2>${worker?'Let local hirers discover your skills.':'Find the right person for your work.'}</h2><ol><li>Create an account and verify your email.</li><li>${worker?'Publish your skills, area, availability and expected pay.':'Create your hirer profile and post a genuine job or task.'}</li><li>${worker?'Apply for jobs or respond to invitations, then agree the work and pay.':'Invite a worker and agree the scope, schedule and pay together.'}</li></ol><p>${worker?'Work earnings go to your connected bank when online payments are activated. You can also agree cash or a direct bank transfer.':'You can agree cash or a direct bank transfer while online payments await activation.'}</p><div class="row-actions">${btn(worker?'Create a worker profile':'Create a hirer profile',worker?'be-worker':'be-employer',true)}${state.user?'':btn('Already have an account? Sign in','auth-login')}</div><p class="caption">LocHire connects people; profiles are self-reported and work is not guaranteed. Review the person and work details before accepting.</p></section>`;}
async function shareJoin(target){const url=new URL('/#join-'+target,location.origin).href;const text=target==='worker'?'Find local work with LocHire. Publish your skills, area and availability.':'Find local workers with LocHire. Post your job or task and agree work directly.';if(navigator.share){try{await navigator.share({title:'LocHire',text,url});return;}catch(e){if(e.name==='AbortError')return;}}if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text+' '+url);toast('Invitation link copied.');return;}catch{}}modal('Invite someone to LocHire','Copy this link and send it to someone who wants to join.',`<p>${esc(text)}</p><p><a href="${esc(url)}">${esc(url)}</a></p>`);}
function home(){const p=own(),name=state.user?.name?.split(' ')[0];main.innerHTML=`<section class="hero simple-hero"><div class="hero-intro"><span class="hero-tag">${icon('pin')} Work and help, close to you</span>${name?`<p class="welcome-line">Welcome, ${esc(name)}.</p>`:''}<h1>Find local workers.<br><span>Find work near you.</span></h1><p>Good work starts with the right person.<br>What would you like to do?</p><div class="hero-actions role-choices"><button type="button" class="role-choice find-choice" data-action="find-work"><span class="choice-icon">${icon('work')}</span><span><strong>I need a job</strong><small>See jobs and get hired</small></span>${icon('arrow')}</button><button type="button" class="role-choice hire-choice" data-action="hire"><span class="choice-icon">${icon('people')}</span><span><strong>I want to hire</strong><small>Find someone to help you</small></span>${icon('arrow')}</button></div><p class="hero-assurance">${icon('shield')} For adults 18 and above · Your details stay in your account</p></div></section><section class="profile-nudge"><span class="nudge-icon">${icon('user')}</span><div><strong>${p?'Your profile is saved':'Let people know what you do'}</strong><p>${p?'Keep it up to date so people can find you.':'Add your skills and area. Hirers can see your profile for free.'}</p></div>${btn(p?'My profile':'Create my profile',p?'profile':'edit-profile',true)}</section>${role==='employer'&&state.employer?radarBanner():''}<section class="home-guide"><div class="section-heading"><h2>How it works</h2><span class="caption">3 easy steps</span></div><ol class="how-it-works"><li><strong>Find a person or job</strong><span>Choose what you need nearby.</span></li><li><strong>Talk and agree</strong><span>Agree the pay, start and end date.</span></li><li><strong>Finish and leave a review</strong><span>Reviews open after the job ends.</span></li></ol></section>${disclosure('home-more','What kind of help?',`<div class="home-categories">${D.categories.map(c=>`<button data-action="category" data-value="${esc(c)}">${icon('work')}${esc(c)}</button>`).join('')}</div><div class="row-actions">${btn('Create worker profile','be-worker')}${btn('Create hirer profile','be-employer')}</div>`,'Cleaning, cooking, repairs and more')}`;}

function discover(){const hiring=role==='employer',active=[category,city,minimum,radius].filter(Boolean).length;main.innerHTML=head(hiring?'Find a worker.':'Find a job.',hiring?'See all workers. Choose an area or skill if you want.':'See jobs near you. Premium lets you read the full job and apply.',hiring?btn('Post a job '+icon('arrow'),'post',true):'')+`${hiring&&state.employer?radarBanner():''}<div class="browse-toolbar"><label class="search">${icon('search')}<input id="discovery-search" type="search" aria-label="Search" placeholder="${hiring?'What do you need help with?':'Search jobs or services'}" value="${esc(q)}"></label></div>${disclosure('filters','Choose area or skill',`<div class="live-filters">${select('search-category','Service',[['','All services'],...D.categories],category)}${field('search-city','City / area',city,'search','maxlength="90"')}${hiring?select('search-rating','Rating',[['','Any rating'],['3','3+ stars'],['4','4+ stars'],['5','5 stars']],minimum)+select('search-sort','Sort by',[['recent','Recent'],['rating','Highest rated'],['nearest','Nearest']],sort):''}</div>${hiring?`<div class="nearby-controls">${select('search-radius','Distance',[['','Any distance'],['1000','Within 1 km'],['5000','Within 5 km'],['10000','Within 10 km'],['30000','Within 30 km']],radius)}<div class="row-actions">${btn(icon('pin')+(locationPoint?' Update location':' Use my location'),'locate')}${locationPoint?btn('Clear location','clear-location'):''}</div><p class="caption">Location is optional. Distances are approximate.</p></div>`:''}<button type="button" class="text-button" data-action="clear-filters">Clear all filters</button>`,active?active+' active':'Service, area and more')}<div id="active-discovery-filters" aria-live="polite"></div><div id="discovery-list" aria-live="polite"></div>`;renderDiscovery();}

function renderDiscovery(){const el=document.querySelector('#discovery-list');if(!el)return;const active=[q&&'Search: '+q,category,city,minimum&&minimum+'+ stars',radius&&'Within '+Number(radius)/1000+' km'].filter(Boolean);const summary=document.querySelector('#active-discovery-filters');if(summary)summary.innerHTML=active.length?`<p class="caption">${active.map(esc).join(' · ')}</p>${btn('Clear all filters','clear-filters')}`:'';const note=document.querySelector('[data-disclosure="filters"] summary small');if(note)note.textContent=active.length?active.length+' active':'Service, area and more';const aliases={plumber:'plumbing',cook:'cooking',cleaner:'cleaning',driver:'driving',electrician:'electrical work',carpenter:'carpentry'},term=aliases[D.norm(q)]||D.norm(q),hiring=role==='employer';let list=(hiring?state.workers.filter(p=>p.published!==false&&!p.suspended):state.openings.filter(o=>o.status==='Open'&&(!o.employerId||o.employerId!==state.employer?.id))).filter(p=>(!term||D.norm([p.name,p.title,p.occupation,p.category,p.speciality,...(p.skills||[])].join(' ')).includes(term))&&(!category||(p.occupation||p.category)===category)&&(!city||D.norm(p.city+' '+p.area+' '+(p.coverage||[]).join(' ')).includes(D.norm(city)))&&(!hiring||!minimum||rating(p.id).average>=Number(minimum))&&(!hiring||!radius||p.distance&&p.distance.metres<=Number(radius)));if(hiring&&sort==='rating')list.sort((a,b)=>rating(b.id).average-rating(a.id).average);if(hiring&&sort==='nearest')list.sort((a,b)=>(a.distance?.metres??Infinity)-(b.distance?.metres??Infinity));el.innerHTML=`<div class="section-heading"><h2>${list.length} ${hiring?'workers':'openings'}</h2><button class="text-button" data-action="refresh">Refresh</button></div>`+(list.length?`<div class="cards">${list.map(p=>hiring?workerCard(p):openingCard(p)).join('')}</div>`:empty(active.length?'No matches for these filters.':hiring?'New workers start here.':'New opportunities start here.',active.length?'Clear the filters to see all published '+(hiring?'workers.':'openings.'):hiring?'No published workers are available yet. Invite a worker to create a profile.':'No openings are available yet. Publish your profile so hirers can find you.',btn('Create a work profile','be-worker',true)+btn(hiring?'Invite a worker':'Invite a hirer',hiring?'share-worker':'share-hirer')));}
function activityBadge(p){
 if(p.acceptingBookings===false)return badge('Unavailable');
 if(p.start>D.today())return badge('Available from '+p.start);
 return `<span class="availability-badge ${p.activity?.activeNow?'active-now':''}"><span class="live-dot" aria-hidden="true"></span>${p.activity?.activeNow?'Active now · Ready to work':'Ready to work'}</span>`;
}
function radarBanner(){const count=(state.workerMatches||[]).length;return `<section class="panel radar-banner"><div><span class="live-label"><span class="live-dot" aria-hidden="true"></span> LIVE MATCHES</span><h2>${count?count+' '+(count===1?'profile matches':'profiles match')+' your openings':'Find your next local worker'}</h2><p>Available people, matched by skills and area.</p></div>${btn('View live matches'+(count?' · '+count:''),'available',true)}</section>`;}
function availabilityPanel(p){return `<section class="panel availability-panel"><div class="section-heading"><h2>${p.acceptingBookings===false?'Your availability is paused':'Ready for your next opportunity'}</h2>${btn(p.acceptingBookings===false?'I’m available':'Pause availability','availability-toggle',false,p.suspended?'disabled':'')}</div><p>${p.published&&p.promoteProfile!==false?'Your profile can reach hirers with matching local openings.':'Publish your profile and enable local matching to reach hirers.'} Interview invitations are saved in your inbox and My work.</p></section>`;}
function availablePage(){
 if(role!=='employer'){main.innerHTML=head('Live worker matches.','Available workers for local hirers.')+empty('Switch to Hiring to review workers.','This feed is available to hirers.',btn('Switch to Hiring','hire',true));return;}
 if(!state.user||!state.employer){main.innerHTML=head('Live worker matches.','Find available people close to your work.')+empty('Create your hirer profile.','Post an opening so LocHire can match occupation, skills and area.',btn('Create hirer profile','be-employer',true));return;}
 const matches=(state.workerMatches||[]).filter(m=>person(m.workerId)),openings=state.openings.filter(o=>o.employerId===state.employer.id&&o.status==='Open');
 main.innerHTML=head('Ready for work.','Review local profiles. Invite the right person for an interview.',btn('Refresh','refresh'))+`<div class="radar-summary"><span class="live-label"><span class="live-dot" aria-hidden="true"></span> LIVE MATCHES</span><span>${matches.length} suggested profiles · ${matches.filter(m=>person(m.workerId)?.activity?.activeNow).length} active now</span></div><p class="caption">Active now means activity within the last 90 seconds. Matches use self-reported skills and general area. Review the profile before deciding.</p>`+(matches.length?`<div class="cards match-cards">${matches.map(m=>{const p=person(m.workerId),o=state.openings.find(o=>o.id===m.openingId);return `<article class="card match-card"><div class="card-top"><span class="avatar">${esc(p.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span>${activityBadge(p)}</div><h3>${esc(p.name)}</h3><p>${esc(p.occupation)} · ${esc(p.speciality)}</p><p class="meta">${icon('pin')} ${esc(p.area)}, ${esc(p.city)}</p>${ratings(p.id)}<p class="rate">${esc(rate(p))}</p><div class="match-reasons"><strong>Matches ${esc(o?.title||'your opening')}</strong><ul>${m.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul></div>${p.activity?.lastActiveAt&&!p.activity.activeNow?`<p class="caption">Last active ${at(p.activity.lastActiveAt)}</p>`:''}<div class="match-actions">${btn('Accept for interview','match-accept',true,pidAttr(m.id))}${btn('Decline','match-decline',false,pidAttr(m.id))}${btn('View profile','view-person',false,pidAttr(p.id))}</div></article>`;}).join('')}</div>`:empty(openings.length?'Matching people will appear here.':'Post your first opening.',openings.length?'Publish clear skills and a general area. Workers who are ready for matching will appear automatically.':'Tell us the occupation, skills and area you need.',btn('Post a job','post',true)+btn('Browse all workers','discover')))+`<p class="caption">Accepted interview invitations stay in My work. Declined suggestions stay hidden for this opening. Manage candidate alerts in your hirer profile and work emails in Settings.</p>`;
}
function acceptMatch(id){const m=(state.workerMatches||[]).find(m=>m.id===id),p=m&&person(m.workerId),o=m&&state.openings.find(o=>o.id===m.openingId);if(!p||!o)return toast('Refresh to see current worker matches.');modal('Invite '+p.name+' for an interview','Review the profile, then share the details they need to attend.',`<form id="interview-form" ${pidAttr(id)} data-engagement="${esc('ENG-'+m.openingId+'-'+m.workerId)}"><p><strong>${esc(o.title)}</strong> · ${esc(p.occupation)}</p><div class="two-fields">${field('date','Interview date',D.today(),'date',`required min="${D.today()}"`)}${field('time','Interview time (WAT)','','time','required')}</div>${textarea('location','Interview address or online meeting link',o.area+', '+o.city)}${field('contactName','Contact person',state.employer.name,'text','required maxlength="100"')}${field('phone','Contact phone',state.user.phone,'tel','required maxlength="30" pattern="(0|\\+234)[0-9]{10}"')}${field('contactEmail','Contact email (optional)',state.user.email,'email','maxlength="254"')}${textarea('notes','What to bring / other instructions','',false)}${check('shareDetails','Send this location and contact information to the worker by email and in their LocHire account.')}<p class="caption">This invites an interview. You can agree the job and pay together after the worker responds.</p>${errorBox()}<button type="submit" class="button primary">Accept & send interview invitation</button></form>`);}
function declineMatch(id){const m=(state.workerMatches||[]).find(m=>m.id===id),p=m&&person(m.workerId);if(!p)return;modal('Decline this profile?','This suggestion will be hidden for this opening.',`<form id="match-decline-form" ${pidAttr(id)}><p>${esc(p.name)} can still be considered for other openings.</p>${errorBox()}<button type="submit" class="button secondary">Decline profile</button></form>`);}
function interviewPanel(g){const t=g.interview;return `<section class="panel interview-panel"><span class="live-label">INTERVIEW INVITATION</span><h2>${g.status==='Pending'?'You have an interview invitation':g.status==='Declined'?'Interview declined':g.status==='Cancelled'?'Interview cancelled':'Interview '+(t.response==='confirmed'?'confirmed':'details')}</h2><p>${esc(person(g.employerId)?.name||'Hirer')} · ${esc(g.title)}</p>${detail([['When',t.date+' · '+t.time+' WAT'],['Location',t.location],['Contact person',t.contactName],['Phone',t.phone],['Email',t.contactEmail],['Instructions',t.notes]])}<p class="caption">Saved to your LocHire account. Agree the work and pay together before starting a job.</p>${!['Cancelled','Declined'].includes(g.status)?btn('Save to calendar','save-interview',false,pidAttr(g.id)):''}</section>`;}
function saveInterview(id){
 const g=engagement(id);if(!g?.interview)return;
 const t=g.interview,start=new Date(t.date+'T'+t.time+':00+01:00'),end=new Date(start.getTime()+3600000);
 const stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
 const clean=v=>String(v||'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
 const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//LocHire//Interview//EN','BEGIN:VEVENT','UID:'+clean(g.id)+'@lochire.ng','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(start),'DTEND:'+stamp(end),'SUMMARY:'+clean('LocHire interview: '+g.title),'LOCATION:'+clean(t.location),'DESCRIPTION:'+clean('Contact: '+t.contactName+' '+t.phone+' '+t.contactEmail+'\n'+t.notes),'END:VEVENT','END:VCALENDAR'].join('\r\n');
 const url=URL.createObjectURL(new Blob([content],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='LocHire-interview.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function workerCard(p){return `<article class="card"><div class="card-top"><span class="avatar">${esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>${p.id===state.worker?.id?badge('Your profile'):role==='employer'?activityBadge(p):badge(p.acceptingBookings===false?'Unavailable':'Accepting enquiries')}</div><h3>${esc(p.name)}</h3><p>${esc(p.occupation)} · ${esc(p.speciality)}</p><p class="meta">${icon('pin')} ${esc(p.area)}, ${esc(p.city)}</p>${ratings(p.id)}${p.distance?`<p class="caption">Approx. ${(p.distance.metres/1000).toFixed(1)} km away</p>`:''}<p class="rate">${esc(rate(p))}</p><div class="card-bottom">${btn('View profile','view-person',false,pidAttr(p.id))}</div></article>`;}
function openingCard(o){return `<article class="card ${o.locked?'locked-job':''}"><div class="card-top">${badge(o.type)}${o.locked?'<span class="badge premium-badge">Locked · Premium</span>':icon('work')}</div><h3>${esc(o.title)}</h3><p>${o.locked?'Upgrade to see the full job details and contact the hirer through LocHire.':esc((o.description||'').slice(0,160))}</p><p class="meta">${icon('pin')} ${esc(o.area)}, ${esc(o.city)}</p><p class="rate">${esc(rate(o,true))}</p><div class="card-bottom">${btn(o.locked?'Unlock this job':'View opening','view-opening',false,pidAttr(o.id))}</div></article>`;}

function profilePage(){if(!state.user){main.innerHTML=head('A profile that opens doors.','Let the right people get to know you.')+empty('Your next step starts here.','Sign in with the same email to restore your saved worker and hirer profiles.',btn('Create account','auth-register',true)+btn('Sign in','auth-login'));return;}const p=own();main.innerHTML=head(role==='worker'?'Your work profile.':'Your employer profile.','Saved to '+state.user.email+'. Worker and hirer profiles share this account.',btn(p?'Edit profile':'Create profile','edit-profile',true))+((role==='worker'?state.employer:state.worker)?`<p class="caption">Your ${role==='worker'?'hirer':'worker'} profile is also saved. ${btn('Switch to '+(role==='worker'?'Hiring':'Find work'),'role-'+(role==='worker'?'employer':'worker'))}</p>`:'')+(p?`<section class="profile-overview"><span class="avatar">${esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><h2>${esc(p.name)}</h2><p>${esc(p.occupation||p.type)} · ${esc(p.area)}, ${esc(p.city)}</p>${badge(p.suspended?'Suspended pending review':p.published?'Published':'Hidden')}</section>${role==='worker'?availabilityPanel(p):''}<div class="settings-menu">${menuRow('View public profile','person/'+p.id,'user')}${role==='employer'?menuRow('Live worker matches','available','people','Available people for your openings')+menuRow('My job posts','openings','work'):''}${menuRow('Premium access','premium','star')}${menuRow('Settings','settings','settings')}</div>`:empty('Make your introduction.','Add your skills, area and availability.',btn('Create profile','edit-profile',true)));}
function settingsPage(){const p=own(),pref=window.LocHireTheme?.preference||'system';main.innerHTML=head('Settings.','Make LocHire feel like yours.')+`<section class="panel appearance-panel"><div class="section-heading"><h2>Appearance</h2>${icon(pref==='dark'?'moon':'sun')}</div><p>Choose a look, or follow your phone.</p><div class="theme-picker" aria-label="Appearance">${[['light','Light','sun'],['dark','Dark','moon'],['system','Device','device']].map(([value,label,i])=>`<button data-action="theme-${value}" aria-pressed="${pref===value}">${icon(i)}<span>${label}</span></button>`).join('')}</div></section><div class="settings-menu">${menuRow(state.user?'Account & security':'Sign in / create account','account','user')}${menuRow('Password & security','password','shield','Change password or request a reset email')}${state.user&&!state.user.emailVerified?menuRow('Verify your email','check-email','mail','Confirm your account email'):''}${menuRow('Premium & job alerts','premium','star')}${menuRow('Switch how you use LocHire','role-menu','people',role==='worker'?'Currently finding work':'Currently hiring')}</div>${state.user?disclosure('work-email','Work email alerts',`<form id="email-preferences-form">${check('enabled','Email me about invitations, messages and work updates.',state.user.emailAlertsEnabled!==false)}<p class="caption">${state.user.emailVerified?'Sent to your verified account email.':'Verify your account email to receive work updates.'} Security and password-reset emails stay enabled.</p>${errorBox()}<button type="submit" class="button secondary">Save email preference</button></form>`,state.user.emailAlertsEnabled===false?'Off':'On'):''}${p&&role==='worker'?disclosure('nearby','Location sharing',`<p>Sharing is optional. Searches show approximate distance; exact coordinates stay private.</p><div class="row-actions">${btn(p.coordinates?'Update location':'Share current location','share-location')}${p.coordinates?btn('Remove location','remove-location'):''}</div><p class="caption">${p.coordinates?'Last shared '+at(new Date(p.coordinates.at).toISOString())+'. Expires after 24 hours.':'No location shared.'}</p>`,p.coordinates?'Location shared':'Currently off'):''}${state.user?disclosure('blocked','Blocked profiles',state.blocks.filter(b=>b.actor===p?.id).map(b=>`<p>Blocked profile ${btn('Unblock','unblock',false,pidAttr(b.target))}</p>`).join('')||'<p>No blocked profiles.</p>','Manage unwanted contact'):''}<div class="settings-menu">${menuRow('Help & support','help','mail')}${menuRow('Privacy','privacy','shield')}${menuRow('Hiring guidance & terms','guidelines','work')}${state.admin?menuRow('Admin dashboard','admin','shield','Users, growth and reports'):''}</div>`;}

function profileForm(){if(!state.user){main.innerHTML=empty('Sign in to create your profile.','Your profile is saved to your account.',btn('Sign in','auth-login',true));return;}const worker=role==='worker',p=own()||{name:state.user.name,city:'',area:'',occupation:'Domestic help',days:['Mon','Tue','Wed','Thu','Fri'],types:['Ongoing job','One-off task'],hoursStart:'08:00',hoursEnd:'17:00',start:D.today(),basis:'Monthly',accommodation:'Live-out',published:true,acceptingBookings:true,type:'Household'};main.innerHTML=head(worker?'Create your worker profile.':'Create your hirer profile.','Your account email and phone stay private.')+`<form id="profile-form" class="panel live-form"><h2>About you</h2><div class="two-fields">${field('name',worker?'Name':'Your name / household / business',p.name,'text','required maxlength="70"')}${field('city','City',p.city,'text','required maxlength="70"')}</div>${field('area','Your area',p.area,'text','required maxlength="90"')}${worker?`<h2>Your skills</h2><div class="two-fields">${select('occupation','What work do you do?',D.categories,p.occupation)}${field('speciality','What are you good at?',p.speciality,'text','required maxlength="100"')}</div>${field('skills','Your skills (put a comma between skills)',(p.skills||[]).join(', '),'text','maxlength="1500"')}${disclosure('experience','Experience & background',`${field('years','Years of experience',p.years||0,'number','min="0" max="60"')}${textarea('experience','Work experience',p.experience,false)}`,'Optional work history')}${disclosure('availability','Availability & work preferences',`<h2>Availability</h2>${multi('types','Types of work',['Ongoing job','One-off task'],p.types)}${multi('days','Working days',D.days,p.days)}<div class="two-fields">${field('hoursStart','Work starts at',p.hoursStart,'time','required')}${field('hoursEnd','Work finishes at',p.hoursEnd,'time','required')}${field('start','Available from',p.start,'date','required')}${field('coverage','Other areas covered (comma separated)',(p.coverage||[]).join(', '))}</div>${check('travel','Willing to discuss travel',p.travel)}`,'Working days, hours and areas covered')}<h2>Expected pay</h2><div class="two-fields">${field('pay','Expected pay (₦)',p.pay||'','number','min="0" max="100000000" step="0.01"')}${select('basis','How often is the pay?',D.bases,p.basis)}</div>${check('flexible','Price depends on the task',p.flexible)}${select('accommodation','Will you stay at the workplace?',['Live-in','Live-out','Either','Not applicable'],p.accommodation)}<details class="optional-details"><summary>Previous work and licence details (optional)</summary>${textarea('workExample','Previous work',p.workExample,false)}${field('licence','Driving licence information (if relevant)',p.licence||'','text','maxlength="200"')}</details>${disclosure('visibility','Profile visibility',check('published','Show my profile to hirers',p.published!==false)+check('acceptingBookings','Ready to receive work enquiries',p.acceptingBookings!==false)+check('promoteProfile','Send my published profile to matching local hirers.',p.promoteProfile!==false)+'<p class="caption">Hirers receive your skills, general area and availability. Your account phone and email stay private.</p>','Choose whether people can find you')}`:`${select('type','Employer type',['Individual','Household','Business'],p.type)}${textarea('intro','A short introduction',p.intro)}${textarea('business','Business details (required for businesses)',p.business,false)}${check('candidateAlerts','Notify me when local workers match my openings.',p.candidateAlerts!==false)}`}<p class="note">Describe your experience honestly. Identity, licences and references are not independently verified.</p>${errorBox()}<div class="row-actions"><button type="submit" class="button primary">Save profile</button>${btn('Cancel','profile')}</div></form>`;}
function openingsPage(){const list=state.openings.filter(o=>o.employerId===state.employer?.id);main.innerHTML=head('Your openings.','Post an ongoing role or one-off task.',btn('Post a job','post',true))+(list.length?`<div class="cards">${list.map(openingCard).join('')}</div>`:empty('What help do you need?','Add clear work details, a general area and your budget.',btn('Post a job','post',true)));}
function openingForm(){if(!state.user||!state.employer){main.innerHTML=empty('Create an employer profile first.','Introduce yourself before posting work.',btn('Create employer profile','be-employer',true));return;}const p=state.openings.find(o=>o.id===routeId)||{type:'Ongoing job',category:'Domestic help',city:state.employer.city,area:state.employer.area,basis:'Monthly',days:['Mon','Tue','Wed','Thu','Fri'],hoursStart:'09:00',hoursEnd:'17:00',start:D.today(),date:D.today(),accommodation:'Live-out'},task=p.type==='One-off task';main.innerHTML=head(p.id?'Edit opening.':'What help do you need?','Give people enough information to decide whether the work suits them.')+`<form id="opening-form" class="panel live-form" ${pidAttr(p.id||'')} data-request="${crypto.randomUUID()}">${select('type','Type of work',['Ongoing job','One-off task'],p.type)}${select('category','Service / occupation',D.categories,p.category)}${field('title','Job name',p.title||'','text','required maxlength="100"')}${textarea('description','What should the worker do?',p.description||'')}<div class="two-fields">${field('city','City',p.city,'text','required maxlength="70"')}${field('area','Your area',p.area,'text','required maxlength="90"')}</div>${field('postcode','Postcode (optional; shared after acceptance)',p.postcode||'','text','maxlength="30"')}<p class="caption">Manual postcodes are not verified. Keep street addresses out of public descriptions.</p><div class="two-fields">${field('min','Lowest pay (₦)',p.min||'','number','min="0" max="100000000" step="0.01"')}${field('max','Highest pay (₦)',p.max||'','number','min="0" max="100000000" step="0.01"')}</div>${select('basis','How often is the pay?',D.bases,p.basis)}${check('quote','Request a quote',p.quote)}${field('skills','Required skills (comma separated)',(p.skills||[]).join(', '),'text','maxlength="1500"')}${field('years','Relevant experience requested (years)',p.years||0,'number','min="0" max="60"')}<div data-work-fields="ongoing" ${task?'hidden':''}>${multi('days','Working days',D.days,p.days||[])}<div class="two-fields">${field('hoursStart','Work starts at',p.hoursStart||'','time')}${field('hoursEnd','Work finishes at',p.hoursEnd||'','time')}</div>${field('start','Job start date',p.start,'date',`min="${D.today()}"`)}</div><div data-work-fields="task" ${task?'':'hidden'}>${field('date','Preferred date',p.date||D.today(),'date',`min="${D.today()}"`)}${field('duration','Estimated duration',p.duration||'','text','maxlength="100"')}${field('materials','Materials / tools',p.materials||'','text','maxlength="300"')}</div>${select('accommodation','Accommodation',['Live-in','Live-out','Either','Not applicable'],p.accommodation)}${errorBox()}<button type="submit" class="button primary">Save opening</button> ${btn('Cancel','openings')}</form>`;}
function personPage(){const p=person(routeId);if(!p){main.innerHTML=empty('Profile unavailable.','This profile may be hidden or no longer available.',btn('Browse','discover'));return;}const worker=!!p.occupation,mine=[state.worker?.id,state.employer?.id].includes(p.id),rr=state.reviews.filter(r=>r.target===p.id);main.innerHTML=head(p.name,(p.occupation||p.type)+' · '+p.area+', '+p.city)+`<div class="profile-columns"><div><section class="panel"><h2>${worker?'What I can offer':'About this hirer'}</h2><p>${esc(worker?p.experience||p.speciality:p.intro)}</p>${worker?(role==='employer'?activityBadge(p):'')+ratings(p.id)+detail([['What are you good at?',p.speciality],['Skills',p.skills.join(', ')],['Experience',p.years+' years, self-reported'],['Work types',p.types.join(', ')],['Days',p.days.join(', ')],['Hours',p.hoursStart+' – '+p.hoursEnd+' WAT'],['Available from',p.start],['Expected pay',rate(p)],['Areas covered',p.coverage.join(', ')],['Accommodation',p.accommodation]])+`<h3>Previous work</h3><p>${esc(p.workExample||'No example added.')}</p>`:`<p>${esc(p.business||'')}</p>`}</section><section class="panel"><h2>Reviews from finished jobs</h2><p class="caption">Hirers can read these reviews before choosing a worker.</p>${rr.length?rr.map(r=>`<article class="review"><strong>${icon('star')} ${r.rating} / 5 · ${esc(person(r.author)?.name||'Hirer')}</strong><span class="badge">Finished job</span><p>${esc(r.text)}</p><span class="caption">${at(r.at)}</span></article>`).join(''):'<p>No reviews yet.</p>'}</section>${!worker?`<section class="panel"><h2>Openings</h2>${state.openings.filter(o=>o.employerId===p.id&&o.status==='Open').map(openingCard).join('')||'<p>No current openings.</p>'}</section>`:''}</div><aside><section class="panel"><h2>Before deciding</h2><p>Work details are self-reported. Agree the scope, pay and schedule together. Exchange private contact details in the conversation when you are comfortable.</p>${worker&&!mine?btn('Request work / invite','invite',true,`${pidAttr(p.id)} ${p.acceptingBookings===false?'disabled':''}`):mine?btn('Edit profile','edit-own-profile',false,`data-role="${worker?'worker':'employer'}"`):''}</section>${!mine?`<div class="safety-actions">${btn('Report profile','report',false,`${pidAttr(p.id)} data-kind="profile"`)}${btn('Block contact','block',false,pidAttr(p.id))}</div>`:''}</aside></div>`;}
function openingPage(){const o=state.openings.find(o=>o.id===routeId);if(!o){main.innerHTML=empty('Opening unavailable.','It may have been closed.',btn('Browse openings','discover'));return;}if(o.locked){main.innerHTML=head(o.title,o.type+' · '+o.area+', '+o.city)+`<section class="panel locked-job-detail"><span class="badge premium-badge">Premium job</span><h2>Unlock the full opportunity</h2><p>${esc(rate(o,true))} · ${esc(o.category)}</p><p>Job details and hirer contact are available with Premium. Choose ₦900 for access, or ₦1,200 with nearby-job email alerts. Each pass lasts 30 days.</p>${btn('Choose your plan','premium',true)}${btn('Back to jobs','discover')}<p class="caption">Your published worker profile stays visible to hirers for free.</p></section>`;return;}const p=person(o.employerId),mine=o.employerId===state.employer?.id;main.innerHTML=head(o.title,o.type+' · '+o.area+', '+o.city)+`<div class="profile-columns"><section class="panel">${badge(o.status)}<h2>Work to be done</h2><p>${esc(o.description)}</p>${detail([['Pay / budget',rate(o,true)],['Skills',o.skills.join(', ')],['Experience',o.years+' years requested'],['Start / date',o.type==='One-off task'?o.date:o.start],['Days',o.days.join(', ')],['Hours',o.hoursStart&&o.hoursStart+' – '+o.hoursEnd+' WAT'],['Duration',o.duration],['Materials',o.materials],['Accommodation',o.accommodation]])}${mine&&o.postcode?`<p class="caption">Private postcode: ${esc(o.postcode)} · Not verified</p>`:''}</section><aside><section class="panel"><h2>Meet the hirer</h2><h3>${esc(p?.name||'Local hirer')}</h3><p>${esc(p?.intro||'')}</p>${btn('View hirer','view-person',false,pidAttr(o.employerId))}</section><section class="panel"><h2>Discuss before deciding.</h2><p>Confirm the scope, schedule and pay together.</p>${mine?btn('Edit opening','edit-opening',false,pidAttr(o.id))+btn(o.status==='Open'?'Close opening':'Reopen opening','opening-status',false,pidAttr(o.id)):o.status==='Open'?btn('Apply for this job','apply',true,pidAttr(o.id)):''}</section>${btn('Report opening','report',false,`${pidAttr(o.id)} data-kind="opening"`)}</aside></div>`;}
function invite(id){role='employer';localStorage.setItem('lochire-role',role);navigation();if(!requireProfile(()=>invite(id)))return;const p=person(id),jobs=state.openings.filter(o=>o.employerId===own().id&&o.status==='Open');modal('Invite '+p.name,'Your request appears in the worker’s LocHire inbox.',`<form id="invite-form" data-worker="${esc(id)}" data-request="${crypto.randomUUID()}">${select('openingId','Invite to an opening',[['','Request a one-off booking'],...jobs.map(o=>[o.id,o.title])])}<div data-booking-fields>${textarea('description','Work needed','')}${field('date','Preferred date',D.today(),'date',`min="${D.today()}"`)}${field('duration','Estimated duration','','text','maxlength="100"')}${field('city','City',state.employer.city)}${field('area','Your area',state.employer.area)}</div>${textarea('message','Message to the worker','Please let me know your availability and price for this work.')}${errorBox()}<button type="submit" class="button primary">Send invitation</button></form>`);}
function apply(id){role='worker';localStorage.setItem('lochire-role',role);navigation();if(!requireProfile(()=>apply(id)))return;if(!state.premium?.active){go('premium');return;}modal('Express interest','Introduce yourself and ask questions about the work.',`<form id="apply-form" data-opening="${esc(id)}">${textarea('message','Your message','')}${errorBox()}<button type="submit" class="button primary">Send interest</button></form>`);}
function engagementsPage(){const list=state.engagements.filter(g=>[g.workerId,g.employerId].includes(own()?.id));main.innerHTML=head('My work.','Your conversations, active jobs and completed work.')+(state.user?list.length?`<div class="stack">${list.map(g=>`<button class="list-row" data-action="record" ${pidAttr(g.id)}><span><strong>${esc(g.title)}</strong><small>${esc(person(g.workerId===own().id?g.employerId:g.workerId)?.name||'Participant')} · ${esc(g.status)}</small></span>${icon('arrow')}</button>`).join('')}</div>`:empty('Start a conversation.','Find suitable work or invite a worker.',btn('Browse','discover',true)):empty('Sign in to see your work.','Engagements are private to participants.',btn('Sign in','auth-login',true)));}
function recordPage(){const g=engagement(routeId);if(!g){main.innerHTML=empty('Engagement unavailable.','Sign in to the account participating in this work.',btn('Sign in','auth-login'));return;}const a=actor(g),other=g.workerId===a?g.employerId:g.workerId,closed=['Completed','Declined','Cancelled'].includes(g.status),payer=a===g.employerId,payments=state.payments.filter(p=>p.engagement_id===g.id);let actions='';const action=(label,op)=>btn(label,'eng-action',true,`${pidAttr(g.id)} data-op="${op}" data-revision="${g.revision}" data-version="${g.version}"`);if(g.status==='Pending'&&a!==g.initiator)actions=action(g.interview?'Confirm interview':'Accept invitation','accept')+action('Decline','decline');if(['Accepted','Confirmed'].includes(g.status))actions+=btn(g.terms?'Propose revised details':'Propose work details','terms',true,pidAttr(g.id));if(g.status==='Accepted'&&g.terms&&g.confirmations[a]!==g.version)actions+=action('I agree to these details','confirm');if(g.status==='Confirmed'&&!g.completion[a])actions+=action('The job is finished','complete');if(g.status==='Completed'&&g.reviewEligibility?.allowed&&!state.reviews.some(r=>r.engagementId===g.id&&r.author===a))actions+=btn('Leave a review','review',true,pidAttr(g.id));main.innerHTML=head(g.title,'With '+(person(other)?.name||'a participant'))+`<div class="profile-columns"><div><section class="panel">${badge(g.status)}<h2>Conversation</h2><div class="message-thread">${g.messages.slice(-100).map(m=>`<article class="message ${m.actor===a?'own':''}"><strong>${esc(person(m.actor)?.name||'Participant')}</strong><p>${esc(m.text)}</p><small>${at(m.at)}</small></article>`).join('')}</div>${!closed?`<form id="message-form" ${pidAttr(g.id)}>${textarea('text','Write a message','')}${errorBox()}<button type="submit" class="button primary">Send message</button></form>`:''}</section>${disclosure('work-direct','Cash & direct transfers',` <p>Cash and bank transfers are made directly between participants. LocHire records their acknowledgements and does not move or hold the money.</p>${payments.map(p=>`<article class="payment-record"><strong>${money(p.amount/100)} · ${p.method==='cash'?'Cash':'Bank transfer'}</strong><p>${esc(p.status==='reported'?'Reported by hirer, awaiting worker acknowledgement':p.status==='acknowledged'?'Acknowledged by worker':'Disputed by worker')}</p><p>${esc(p.note)}</p><span class="caption">${esc(p.id)} · ${at(p.created_at)}</span>${!payer&&p.status==='reported'?`<div class="row-actions">${btn('I received this payment','payment-ack',true,`${pidAttr(p.id)} data-eng="${g.id}" data-status="acknowledged"`)}${btn('I have not received it','payment-ack',false,`${pidAttr(p.id)} data-eng="${g.id}" data-status="disputed"`)}</div>`:''}</article>`).join('')||'<p>No payment recorded.</p>'}${payer&&['Confirmed','Completed'].includes(g.status)?btn('Record payment sent','record-payment',false,pidAttr(g.id)):''}`,payments.length+' records',!payer&&payments.some(p=>p.status==='reported'))}</div><aside>${g.interview?interviewPanel(g):''}<section class="panel"><h2>Agreed work details</h2>${g.terms?`<p class="agreement-pay">${money(g.terms.pay)} / ${esc(g.terms.basis)}</p><p>${esc(g.terms.scope)}</p>${disclosure('agreement','Schedule & full agreement',detail([['Scope',g.terms.scope],['Pay',money(g.terms.pay)+' / '+g.terms.basis],['Schedule',g.terms.schedule],['Starts',D.friendlyDate(g.terms.start)],['Ends',g.terms.completionDate?D.friendlyDate(g.terms.completionDate):'Not agreed'],['Area',g.terms.area+', '+g.terms.city],['Payment method',g.terms.paymentMethod==='cash'?'Cash':'Direct bank transfer'],['Materials',g.terms.materials],['Accommodation',g.terms.accommodation]]),'Read the job dates, pay and work',g.status==='Accepted'&&g.confirmations[a]!==g.version)}`:'<p>No work details proposed yet.</p>'}${g.postcode?`<p class="caption">Shared postcode: ${esc(g.postcode)} · Not verified</p>`:''}${g.terms?`<p class="caption">Worker: ${g.confirmations[g.workerId]===g.version?'confirmed':'awaiting confirmation'}<br>Hirer: ${g.confirmations[g.employerId]===g.version?'confirmed':'awaiting confirmation'}</p>`:''}${g.completion[a]&&g.status!=='Completed'?'<p>Your side is marked complete. Waiting for the other participant.</p>':''}${g.terms&&!state.reviews.some(r=>r.engagementId===g.id&&r.author===a)?`<div class="review-lock" role="status">${icon(g.reviewEligibility?.allowed?'star':'calendar')}<div><strong>${g.reviewEligibility?.allowed?'You can now leave a review':'Review opens after the job ends'}</strong><p>${esc(g.reviewEligibility?.allowed?'Your review will be visible to other hirers.':g.reviewEligibility?.reason||'Both people must mark the job finished.')}${!g.reviewEligibility?.allowed&&g.reviewEligibility?.opensAt?' You can review from '+esc(D.friendlyDate(g.reviewEligibility.opensAt))+'.':''}</p></div></div>`:''}<div class="record-actions">${actions}</div></section>${disclosure('work-more','More options',`<div class="row-actions">${btn('View participant','view-person',false,pidAttr(other))}${btn('Report a concern','report',false,`${pidAttr(g.id)} data-kind="engagement"`)}${!closed?action('Cancel engagement','cancel'):''}</div>`,'Participant, support and cancellation')}</aside></div>`;}
function terms(id){const g=engagement(id),t=g.terms||{},o=state.openings.find(o=>o.id===g.openingId);modal('Agree the work details','Both participants must confirm this version. Revisions require fresh confirmations.',`<form id="terms-form" ${pidAttr(id)} data-revision="${g.revision}">${textarea('scope','What work will be done?',t.scope||o?.description||'')}<div class="two-fields">${field('pay','Agreed pay (₦)',t.pay||'','number','required min="1" max="100000000" step="0.01"')}${select('basis','How often is the pay?',D.bases,t.basis||o?.basis||'Per task')}</div>${field('schedule','Days and hours (Nigerian time)',t.schedule||'','text','required maxlength="300"')}<div class="two-fields">${field('start','Job start date',t.start||o?.start||D.today(),'date','required')}${field('completionDate','Job end date',t.completionDate||'','date',`required min="${esc(t.start||o?.start||D.today())}" aria-describedby="job-end-help"`)}${field('city','City',t.city||o?.city||'','text','required maxlength="70"')}${field('area','Your area',t.area||o?.area||'','text','required maxlength="90"')}</div><div class="duration-choices" role="group" aria-label="Choose job length"><span>Choose job length:</span>${btn('1 day','job-length',false,'data-length="day"')}${btn('1 week','job-length',false,'data-length="week"')}${btn('1 month','job-length',false,'data-length="month"')}</div><p id="job-end-help" class="note">Both people must agree this end date. Reviews open after this date has passed, once both people say the job is finished.</p>${select('paymentMethod','Payment method',[['bank_transfer','Direct bank transfer'],['cash','Cash']],t.paymentMethod||'bank_transfer')}${field('materials','Materials / tools',t.materials||'','text','maxlength="300"')}${field('accommodation','Accommodation',t.accommodation||'','text','maxlength="100"')}${errorBox()}<button type="submit" class="button primary">Propose details</button></form>`);}
function report(id,kind='profile'){if(!requireAccount(()=>report(id,kind)))return;modal('Report a concern','Your report is saved privately for the LocHire owner to review. For immediate danger, contact local emergency services.',`<form id="report-form" ${pidAttr(id)} data-kind="${kind}">${select('reason','Reason',['Unwanted contact','Misleading information','Payment concern','Safety concern','Other'])}${textarea('details','What happened?','')}${errorBox()}<button type="submit" class="button primary">Submit report</button></form>`);}
function notificationsPage(){main.innerHTML=head('Your inbox.','Saved invitations, messages and work updates.',state.user?btn('Mark all read','read-all'):'')+(state.user?state.notifications.length?`<div class="stack">${state.notifications.map(n=>`<button class="list-row ${n.read_at?'':'unread'}" ${n.engagement_id?`data-action="record" ${pidAttr(n.engagement_id)}`:n.kind==='job_alert'?'data-page="discover"':n.kind==='worker_match'?'data-page="available"':'data-page="help"'}><span><strong>${esc(n.title)}</strong><small>${at(n.created_at)}</small></span>${icon('arrow')}</button>`).join('')}</div>`:empty('You’re up to date.','New invitations and messages will appear here.'):empty('Sign in to your inbox.','Your updates are private.',btn('Sign in','auth-login',true)));}
let financeLoad=0;
function walletPage(){premiumPage();}
function premiumPage(){
 const manageAlerts=new URL(location.href).searchParams.get('manage_job_alerts')==='1';
 const access=state.premium||{},ready=state.provider?.ready,plans=state.plans||[{id:'access',name:'Premium',amount:90000,days:30,alerts:false},{id:'alerts',name:'Premium Plus',amount:120000,days:30,alerts:true}],test=state.provider?.mode==='test';
 const preferences=state.alertPreferences||{enabled:true,city:state.worker?.city||'',area:state.worker?.area||'',category:state.worker?.occupation||''};
 main.innerHTML=head('More opportunities. Close to you.','Choose the job access that works for you.')+
  (manageAlerts&&!state.user?`<section class="panel"><h2>Manage nearby job emails</h2><p>Sign in with the account that received the email to change your preferences.</p>${btn('Sign in to manage alerts','manage-job-alerts',true)}</section>`:manageAlerts&&!state.worker?`<section class="panel"><h2>Your worker profile</h2><p>Create a worker profile to choose your job alert preferences.</p>${btn('Create worker profile','be-worker',true)}</section>`:'')+
  (test?'<p class="form-status" role="status">Private test checkout · simulated payments. Test passes do not unlock another account or enable live job emails.</p>':'')+
  (access.active?`<section class="panel premium-current"><span class="badge premium-badge">${access.tier==='alerts'?'Premium Plus':'Premium'} active</span><h2>Your jobs are unlocked</h2><p>Access until ${at(access.expiresAt)}.${access.alerts?' Nearby email alerts until '+at(access.alertsExpiresAt)+'.':''}</p>${btn('Explore jobs','discover',true)}</section>`:'')+
  `<div class="premium-plans">${plans.map(plan=>`<section class="panel premium-plan ${plan.alerts?'premium-plus':''}"><span class="badge premium-badge">${plan.alerts?'Access + alerts':'Job access'}</span><h2>${esc(plan.name)}</h2><div class="checkout-amount">${money(plan.amount/100)}<span>One payment · 30 days · no automatic renewal</span></div><ul><li>Unlock full job details and express interest</li><li>Explore jobs in your area or across other locations</li><li>${plan.alerts?'New nearby jobs emailed when they match your preferences':'Find new jobs whenever you open LocHire'}</li></ul>${btn(access.active?'Buy / renew '+esc(plan.name):'Choose '+esc(plan.name),'premium-buy',true,`data-tier="${plan.id}" ${ready?'':'disabled'}`)}</section>`).join('')}</div>`+
  (!ready?'<section class="panel" role="status"><h2>Premium payments open soon</h2><p>Kora checkout is awaiting approval and connection testing. You can create your profile, preview jobs and receive hirer invitations while we finish setup.</p></section>':'')+
  `<p class="caption">Premium belongs to your signed-in account and restores when you sign in on another device. A pass gives access to opportunities; it does not guarantee work. Buying Plus starts a full-price 30-day Plus pass; overlapping passes are not prorated.</p>`+
  (state.user&&state.worker?disclosure('job-alerts','Nearby job email preferences',`<form id="job-alerts-form" class="live-form">${check('enabled','Email me new matching jobs while Premium Plus is active.',preferences.enabled)}${field('city','City',preferences.city,'text','required maxlength="70"')}${field('area','Area (leave blank for the whole city)',preferences.area,'text','maxlength="90"')}${select('category','Service',[['','All services'],...D.categories],preferences.category)}<p class="caption">Alerts use your selected city, area and service. Only newly posted matching jobs are emailed. You can turn them off here at any time. Hirer invitations and account-security emails have separate settings.</p>${errorBox()}<button type="submit" class="button secondary">Save alert preferences</button></form>`,access.alerts?'Included in your Plus pass':'Requires Premium Plus'):'')+
  disclosure('premium-orders','Your premium purchases',(state.premiumOrders||[]).map(o=>`<article class="payment-record"><strong>${o.tier==='alerts'?'Premium Plus':'Premium'} · ${money(o.amount/100)}</strong><p>${esc(o.status)}${o.mode==='test'?' · Test payment':''} · ${at(o.createdAt)}</p><p class="caption">${esc(o.reference)}</p>${btn('Check payment','premium-check',false,pidAttr(o.reference))}</article>`).join('')||'<p>No purchases yet.</p>','Saved to your account')+
  `<section class="panel"><h2>Work payments stay between you</h2><p>Agree salary or task payments directly with the hirer. Exchange bank details privately when you are comfortable. LocHire charges only for its premium services.</p>${btn('My work','engagements')}</section>`;
 if(manageAlerts&&state.user&&state.worker)disclosures.set('premium//job-alerts',true);
 restoreDisclosures();
 if(manageAlerts&&state.user&&state.worker){const panel=main.querySelector('[data-disclosure="job-alerts"]');if(panel){panel.open=true;panel.querySelector('input')?.focus({preventScroll:true});panel.scrollIntoView?.({block:'start'});}const url=new URL(location.href);url.searchParams.delete('manage_job_alerts');history.replaceState(null,'',url.href);}
}
function premiumBuy(tier='access'){
 if(!requireAccount(()=>premiumBuy(tier)))return;
 if(!state.worker){role='worker';localStorage.setItem('lochire-role',role);go('edit-profile');toast('Create and publish your worker profile first.');return;}
 const plan=(state.plans||[]).find(p=>p.id===tier);if(!plan)return toast('Refresh to load the current plans.');
 modal('Get '+plan.name,'This purchase is linked to '+state.user.email+'.',`<form id="premium-purchase-form" data-request="${crypto.randomUUID()}" data-tier="${plan.id}" data-amount="${plan.amount}"><div class="checkout-amount">${money(plan.amount/100)}<span>30 days · one-time payment through Kora</span></div><p>${plan.alerts?'Unlock jobs and receive emails for newly posted jobs matching your city, area and service.':'Unlock full job details and express interest whenever you visit LocHire.'}</p><p>No automatic renewal. Kora confirms the payment before access is unlocked. Processing fees are included in the displayed price.</p>${state.provider?.mode==='test'?'<p class="form-status">Test checkout · use Kora test payment details only.</p>':''}${plan.alerts?check('alertsConsent','I want new matching job emails. I can change or disable them in my premium preferences.'):''}${check('consent','I approve this '+money(plan.amount/100)+' one-time purchase for my account.')}${errorBox()}<button type="submit" class="button primary">Continue to Kora</button></form>`);
}
async function checkPremium(reference){
 const identity=authEpoch,r=await api('payments/premium/verify',{reference});if(identity!==authEpoch)return;await refresh(false);if(dialog.open)dialog.close();go('premium');toast(r.order.status==='success'?'Kora confirmed your payment. Premium is active.':'Payment status: '+r.order.status+'. Access unlocks after Kora confirms success.');
}
async function financePage(){
 const load=++financeLoad;if(!state.admin){main.innerHTML=head('Premium revenue.','Owner access is required.')+empty('Sign in to your owner account.','Your email must be verified.',btn('Open admin sign-in','admin',true));return;}
 main.innerHTML=head('Premium revenue.','Loading confirmed Kora purchases.');
 try{const d=await api('admin/finance');if(load!==financeLoad||page!=='finance')return;main.innerHTML=head('Premium revenue.','Kora payments for LocHire access. Work payments are arranged directly.',btn('Refresh','finance-refresh'))+`<p class="caption">${d.mode==='test'?'Test payments · no real revenue':'Live payments'}. Settlement and bank withdrawals are managed in your Kora dashboard.</p><section class="admin-metrics">${[['Confirmed sales',d.totals.revenue],['Provider fees',d.totals.fees],['Net premium revenue',d.totals.revenue-d.totals.fees]].map(([label,value])=>`<article class="panel admin-metric"><p>${label}</p><strong>${money(value/100)}</strong></article>`).join('')}</section><section class="panel"><h2>Recent premium purchases</h2>${d.orders.map(o=>`<div class="money-history-row"><span>${esc(o.name)} · ${o.tier==='alerts'?'Premium Plus':'Premium'}<small>${esc(o.reference)} · ${esc(o.status)} · ${at(o.createdAt)}</small></span><strong>${money(o.amount/100)}</strong></div>`).join('')||'<p>No purchases yet.</p>'}</section>`;}catch(e){if(page==='finance'&&load===financeLoad)main.innerHTML=head('Premium revenue.','Private owner dashboard.')+empty('Purchases could not load.',e.message,btn('Try again','finance-refresh'));}
}
function checkoutRedirect(r){if(!r.checkoutUrl){toast(r.message||'Your purchase is saved. Use Check payment before starting another.');return false;}const url=new URL(r.checkoutUrl);if(url.protocol!=='https:'||url.hostname!=='checkout.korapay.com'||url.username||url.password||url.port)throw Error('Checkout could not be validated.');window.location.assign(url.href);return true;}

function accountPage(){main.innerHTML=head('Your account.','Your sign-in, security and private details.')+(state.user?`<section class="account-summary"><span class="avatar">${esc(state.user.name[0])}</span><div><strong>${esc(state.user.name)}</strong><p>${esc(state.user.email)}</p></div></section><section class="panel verification-card">${badge(state.user.emailVerified?'Email verified':'Email not verified')}<p>${state.user.emailVerified?'Your account email has been confirmed.':state.emailReady?'Verify your email to finish your profile and arrange work.':'Email verification is awaiting activation. Your account is saved.'}</p>${!state.user.emailVerified?btn('Verify email','check-email',true):''}</section><div class="settings-menu">${menuRow('Password & security','password','shield','Change password or send a reset link')}${menuRow('Appearance & preferences','settings','settings')}</div>${disclosure('account-details','Your private details',detail([['Name',state.user.name],['Email',state.user.email],['Phone',state.user.phone]]),'Contact information')}<div class="row-actions">${btn('Sign out','logout')}</div>`:empty('Welcome to LocHire.','Use your account on any device.',btn('Sign in','auth-login',true)+btn('Create account','auth-register')+btn('Forgot password?','auth-forgot')))+`<div class="settings-menu">${menuRow('Help & support','help','mail')}${menuRow('Privacy','privacy','shield')}</div>`;}
function passwordPage(){main.innerHTML=head('Password & security.','Keep your account secure.')+(state.user?`<form id="password-form" class="panel live-form"><h2>Change your password</h2><p>Use your current password to choose a new one.</p>${field('currentPassword','Current password','','password','required minlength="10" maxlength="200" autocomplete="current-password"')}${field('password','New password','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}${field('confirmPassword','Confirm new password','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}${errorBox()}<button type="submit" class="button primary">Change password</button><p class="caption">You will be signed out on all devices.</p></form>`:'')+`<section class="panel"><h2>Forgot your password?</h2><p>Request a secure link at your account email address. You do not need your current password.</p>${btn('Send a reset email','auth-forgot',!state.user)}${!state.emailReady?'<p class="caption">Email sending is awaiting activation.</p>':''}</section><div class="row-actions">${btn('Back to account','account')}</div>`;}
function checkEmailPage(){if(!state.user){main.innerHTML=head('Verify your email.','Sign in to request a new verification email.')+empty('Your account email stays private.','Use the account you want to verify.',btn('Sign in','auth-login',true));return;}if(state.user.emailVerified){main.innerHTML=head('Your email is verified.','You’re ready for your next step.')+empty('All set.','Continue creating your profile or finding work.',btn('Continue to LocHire','continue-verified',true));return;}main.innerHTML=head('Check your email.','One quick step to confirm your account.')+`<section class="panel email-check"><span class="empty-icon">${icon('mail')}</span><h2>Verify your email address</h2><p class="email-address">${esc(state.user.email)}</p><p>${state.emailReady?'Open the verification email, tap the link and confirm. It brings you back to LocHire. Check your spam folder if it isn’t in your inbox.':'Email sending is awaiting activation. Your account has been created and saved; verification emails will be available once sending is connected.'}</p>${verificationMessage?`<p class="form-status" role="status">${esc(verificationMessage)}</p>`:''}<div class="row-actions">${btn('Resend verification email','verify-email',true,state.emailReady?'':'disabled')}${state.emailReady?btn('I’ve verified — continue','check-verification'):btn('Continue to my profile','profile')}</div><p class="caption">Links expire after one hour. Need another account? ${btn('Sign out','logout')}</p></section>`;}
function emailVerifiedPage(){main.innerHTML=head('Email verified.','Thanks for confirming your account.')+empty('You’re ready to continue.',state.user?.id===verifiedLinkUser?'Your next step is waiting.':'Sign in to the account you just verified.',btn(state.user?.id===verifiedLinkUser?'Continue to LocHire':'Sign in',state.user?.id===verifiedLinkUser?'continue-verified':'auth-login',true));}
function continueVerified(){const next=verificationNext;verificationNext=null;verificationMessage='';if(next)next();else go('profile');}

function helpPage(){main.innerHTML=head('Help & support.','Get help with work details, contact or a payment record.')+`<section class="panel"><h2>Report a concern</h2><p>Use Report on a profile, opening or engagement. Your report is saved privately for the LocHire owner to review.</p>${btn('Contact support','support',true)}</section><section class="panel"><h2>Payments</h2><p>Participants make cash and bank-transfer payments directly. An acknowledgement is not bank verification or payment insurance. Kora checkout is used only for LocHire Premium and Premium Plus passes. Arrange salary and task payments directly with the other participant.</p></section><section class="panel"><h2>Account security</h2><p>Use a unique password. Never share bank OTPs, PINs or passwords. Change your LocHire password in Account settings.</p></section>${state.reports?.length?`<section class="panel"><h2>Your reports</h2>${state.reports.map(r=>`<article class="review"><strong>${esc(r.reason)} · ${esc(r.status)}</strong><p>${esc(r.resolution||'Awaiting review.')}</p><span class="caption">${esc(r.id)}</span></article>`).join('')}</section>`:''}`;}
function privacyPage(){main.innerHTML=head('Your privacy.','How LocHire uses your information.')+`<section class="panel"><h2>Accounts and profiles</h2><p>LocHire stores accounts, hashed passwords, profiles, openings, conversations, reviews, payment acknowledgements and reports on its servers. An HttpOnly cookie keeps you signed in. Browser storage remembers your selected role and appearance preference.</p><p>Your account email and phone stay private. Published profiles share your name, general area, work details and availability. Keep sensitive information out of public descriptions.</p><h2>Location and conversations</h2><p>Location sharing is optional. Exact snapshots stay private; searches return approximate distances for up to 24 hours. Removing your snapshot stops future location-based discovery. Conversations and payment declarations are visible only to participants. An opening’s postcode is shared with the worker after acceptance.</p><h2>Service providers and your choices</h2><p>Kora processes premium purchases using your account name, email, order reference and selected plan. LocHire stores the verified purchase and access expiry. Payment card and bank credentials stay with Kora. Premium Plus emails use your selected city, area and service; you can disable them in Premium preferences. LocHire does not offer a stored-value wallet or escrow. Account email is sent to the email provider when sending is connected and you sign up or request recovery or verification. Hide your work profile, remove its location or sign out in Account. Request data access or account deletion through Help; some work records may need retention for dispute handling.</p></section>`;}
function termsPage(){main.innerHTML=head('Hiring guidance & terms.','Make clear agreements and treat each other respectfully.')+`<section class="panel"><h2>Agree the work</h2><p>LocHire connects workers with hirers. Participants assess suitability and agree scope, pay, schedule and safe working conditions. Information is self-reported unless explicitly verified. Both participants confirm the current work-details version, then completion before reviews become available.</p><h2>Safe payments and contact</h2><p>Do not send recruitment fees to get a job or share banking credentials. Arrange salary and task payments directly using the method you agree with the other participant. Kora checkout is only for optional LocHire premium access. A pass lasts 30 days without automatic renewal; the displayed price includes processing fees. Premium does not guarantee work or a hire. A payment acknowledgement is not a bank-verified transaction. LocHire currently offers no custody, escrow or payment insurance.</p><h2>Community and accounts</h2><p>Do not post misleading information, harass users or use discriminatory criteria. Block unwanted contact and report concerns. Profiles or openings may be hidden during review. Use accurate account details and a secure password. You must be 18 or older to register. Give your real date of birth and follow applicable work rules.</p></section>`;}
function signupChart(days){
  const peak=Math.max(1,...days.map(d=>d.count)),total=days.reduce((n,d)=>n+d.count,0);
  return `<svg class="admin-chart" viewBox="0 0 600 170" role="img" aria-label="${total} signups in the last 30 days. Highest daily count ${peak}."><line x1="0" y1="145" x2="600" y2="145" class="chart-axis"/>${days.map((d,i)=>{const h=d.count/peak*125;return `<rect x="${i*20+3}" y="${145-h}" width="13" height="${h}" rx="3"><title>${esc(d.day)}: ${d.count} signups</title></rect>`;}).join('')}<text x="0" y="166">${esc(days[0]?.day||'')}</text><text x="600" y="166" text-anchor="end">${esc(days.at(-1)?.day||'')}</text></svg>`;
}
function adminReportCards(reports){return reports.map(r=>`<article class="panel"><h3>${esc(r.reason)}</h3>${badge(r.status)}<p>${esc(r.details)}</p><p class="caption">${esc(r.kind)} · ${esc(r.target)} · ${at(r.created_at)}</p>${r.status==='open'?`<form class="admin-report-form" ${pidAttr(r.id)}>${select('action','Action',[['resolve','Record resolution'],['hide_profile','Suspend reported profile'],['close_opening','Close reported opening']])}${textarea('resolution','Resolution / response','')}<button type="submit" class="button primary">Save resolution</button></form>`:`<p>${esc(r.resolution)}</p>`}</article>`).join('')||'<p>No reports yet. Submitted reports will appear here.</p>';}
let adminUsers=[];
function adminLockStatus(u){return u.lock_kind&&u.lock_kind!=='unlocked'&&(!u.lock_until||u.lock_until>Date.now())?(u.lock_kind==='permanent'?'Permanently locked':'Locked until '+at(u.lock_until)):'Active';}
function adminLockForm(u){modal('Manage account access',esc(u.name)+' · '+esc(u.email),`<form id="admin-lock-form" data-id="${esc(u.id)}"><p>${esc(adminLockStatus(u))}</p><p>Locks hide both profiles and job posts and stop account access. Saved data stays safe. Temporary locks end automatically. Permanent locks have no expiry; an admin can unlock them.</p>${select('action','Account action',[['temporary','Lock temporarily'],['permanent','Lock permanently'],['unlocked','Unlock account']])}${field('days','Days for a temporary lock',7,'number','min="1" max="365" step="1" required')}${textarea('reason','Reason for this change (shown to the user)','')}${check('confirm','I have checked this account and want to apply this change.')} ${errorBox()}<button class="button primary" type="submit">Apply account change</button></form>`);}
async function adminPage(){
  const load=++adminLoad;
  if(!state.admin){main.innerHTML=head('Admin dashboard.','Private access for the LocHire owner.')+empty('Administrator access required.',!state.user?'Sign in with your owner account to continue.':!state.user.emailVerified?'Verify the owner account email to unlock the dashboard.':'This account does not have administrator access.',btn(!state.user?'Sign in':!state.user.emailVerified?'Verify email':'Switch account',!state.user?'admin-login':!state.user.emailVerified?'check-email':'account',true));return;}
  main.innerHTML=head('Admin dashboard.','Your users and growth, in one place.')+empty('Loading dashboard','Reading saved LocHire accounts.');
  try{
    const params=new URLSearchParams({q:adminQuery,verified:adminVerified,page:String(adminListPage)});
    const [data,queue]=await Promise.all([api('admin/dashboard?'+params),api('admin/reports')]);
    if(page!=='admin'||load!==adminLoad)return;
    adminListPage=data.pagination.page;adminUsers=data.users;
    const c=data.counts,pg=data.pagination,n=v=>Number(v).toLocaleString('en-NG');
    const cards=[['Total users',c.accounts,'Registered accounts'],['Verified email',c.verified,n(c.unverified)+' awaiting verification'],['New today',c.today,'Since midnight WAT'],['Last 7 days',c.week,'Including today']];
    main.innerHTML=head('Admin dashboard.','Your users and growth, in one place.',btn('Payments','finance',true)+btn('Refresh','admin-refresh'))+`<p class="caption" role="status">Updated ${at(data.generatedAt)} · Counts include your account.</p><section class="admin-metrics" aria-label="Account totals">${cards.map(([label,value,note])=>`<article class="panel admin-metric"><p>${label}</p><strong>${n(value)}</strong><span class="caption">${esc(note)}</span></article>`).join('')}</section><section class="panel"><div class="admin-section-head"><div><h2>Signup growth</h2><p class="caption">Last 30 calendar days · Lagos time</p></div><strong>${n(c.month)} new users</strong></div>${signupChart(data.signups)}${disclosure('signup-days','Daily counts',`<div class="admin-daily">${data.signups.map(d=>`<span>${esc(d.day)}<strong>${n(d.count)}</strong></span>`).join('')}</div>`,'See each day')}</section><section class="panel"><h2>Users</h2><form id="admin-users-form" class="admin-filters">${field('q','Search name or email',adminQuery,'search','maxlength="100" autocomplete="off"')}${select('verified','Email status',[['','Everyone'],['yes','Verified'],['no','Unverified']],adminVerified)}<button type="submit" class="button secondary">Apply filters</button></form><p class="caption">${n(pg.total)} matching ${pg.total===1?'user':'users'} · Page ${pg.page} of ${pg.pages}</p><div class="admin-users">${data.users.map(u=>`<article class="admin-user"><div><h3>${esc(u.name)}</h3><p class="admin-email">${esc(u.email)}</p><span class="caption">Joined ${at(u.created_at)}</span></div><div>${badge(u.email_verified_at?'Verified':'Unverified')}${badge(adminLockStatus(u))}${u.lock_reason?`<p class="caption">Last reason: ${esc(u.lock_reason)}</p>`:''}${u.id!==state.user.id?btn('Manage access','admin-lock',false,pidAttr(u.id)):''}<p class="caption">${n(u.profile_count)} ${u.profile_count===1?'profile':'profiles'}</p></div></article>`).join('')||'<p>No users match your filters.</p>'}</div><div class="row-actions">${btn('Previous','admin-prev',false,pg.page<=1?'disabled':'')}${btn('Next','admin-next',false,pg.page>=pg.pages?'disabled':'')}</div></section>${disclosure('platform','Platform activity',detail([['Worker accounts',n(c.workers)],['Employer accounts',n(c.employers)],['Total profiles',n(c.profiles)],['Job posts',n(c.openings)],['Work engagements',n(c.engagements)],['Completed engagements',n(c.completed)]])+'<p class="caption">One account can have both a worker and an employer profile. These are saved records, not visitor counts.</p>','Profiles and work totals')}${disclosure('email-delivery','Work email delivery',detail([['Accepted by email provider',n(data.emailAlerts?.sent||0)],['Pending / sending',n((data.emailAlerts?.pending||0)+(data.emailAlerts?.sending||0))],['Provider rejected',n(data.emailAlerts?.failed||0)],['Needs review',n(data.emailAlerts?.review||0)],['Alerts off / unverified',n(data.emailAlerts?.skipped||0)]])+'<p class="caption">Pending deliveries retry during later account activity. Review provider errors before resending an uncertain email. Provider acceptance does not confirm inbox delivery.</p>','Delivery status and failures')}${disclosure('reports','Reports & moderation',adminReportCards(queue.reports),n(c.pendingReports)+' awaiting review')}<p class="caption">Statistics are read from the live database. Refresh to see the latest numbers.</p>`;
    restoreDisclosures();
  }catch(e){if(page==='admin'&&load===adminLoad)main.innerHTML=head('Admin dashboard.','Your users and growth, in one place.')+empty('Dashboard could not load.',e.message,btn('Try again','admin-refresh',true));}
}
function resetPage(){main.innerHTML=head('Choose a new password.','Links expire after one hour and can be used once.')+`<form id="reset-form" class="panel live-form">${field('password','New password','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}${field('confirmPassword','Confirm new password','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}${errorBox()}<button type="submit" class="button primary">Reset password</button></form>`;}
function verifyPage(){main.innerHTML=head('Verify your email.','Confirm the email associated with your account.')+`<form id="verify-form" class="panel">${errorBox()}<button type="submit" class="button primary">Verify email & continue</button><p class="caption">Link expired? ${btn('Request another email','check-email')}</p></form>`;}
async function selectRole(next){if(state.user){await api('wallet/role',{role:next});stateEpoch++;state.user.activeRole=next;}if(role!==next)clearDiscoveryFilters();role=next;localStorage.setItem('lochire-role',role);if(dialog.open)dialog.close();navigation();}
function locate(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(Error('Location is unavailable on this device.'));navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lon:p.coords.longitude,accuracy:p.coords.accuracy,at:Date.now()}),e=>reject(Error(e.code===1?'Location permission declined. Search by city instead.':'Could not get your location. Try again or search by area.')),{enableHighAccuracy:true,timeout:10000,maximumAge:30000});});}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.page){if(b.dataset.page==='role-menu'){if(dialog.open)dialog.close();document.querySelector('#role-button').click();}else if(b.dataset.page.startsWith('person/'))go('person',b.dataset.page.slice(7));else go(b.dataset.page);return;}const action=b.dataset.action,id=b.dataset.id;if(!action)return;try{
  if(action==='close'){dialog.close();return;}if(action==='menu'){mainMenu();return;}if(action.startsWith('theme-')){window.LocHireTheme?.set(action.slice(6));return;}if(action==='home'){go('home');return;}if(action==='role'){modal('One account. Two ways to use LocHire.','Choose how you want to use LocHire.',`<div class="modal-menu">${btn('Find work','role-worker',true)}${btn('Hire someone','role-employer',true)}</div>`);return;}if(action.startsWith('auth-')){auth(action.slice(5));return;}b.disabled=true;
  if(action==='role-worker'||action==='role-employer'){await selectRole(action==='role-worker'?'worker':'employer');render();}
  else if(action==='find-work'||action==='hire'){await selectRole(action==='hire'?'employer':'worker');go('discover');}
  else if(action==='category'){await selectRole('employer');category=b.dataset.value;go('discover');}
  else if(action==='be-worker'||action==='be-employer'){await selectRole(action==='be-worker'?'worker':'employer');if(requireAccount(()=>go('edit-profile')))go('edit-profile');}
  else if(action==='edit-own-profile'){await selectRole(b.dataset.role);go('edit-profile');}
  else if(action==='edit-profile'){if(requireAccount(()=>go('edit-profile')))go('edit-profile');}
  else if(action==='admin-login'){pending=()=>go('admin');auth();}
  else if(action==='share-worker'||action==='share-hirer')await shareJoin(action==='share-worker'?'worker':'hirer');
  else if(action==='manage-job-alerts'){if(requireAccount(()=>go('premium')))go('premium');}
  else if(action==='premium-buy')premiumBuy(b.dataset.tier);
  else if(action==='premium-check')await checkPremium(id);
  else if(action==='finance-refresh')financePage();
  else if(action==='admin-lock'){const u=adminUsers.find(u=>u.id===b.dataset.id);if(u)adminLockForm(u);}
  else if(action==='admin-refresh')adminPage();
  else if(action==='admin-prev'){adminListPage=Math.max(1,adminListPage-1);adminPage();}
  else if(action==='admin-next'){adminListPage++;adminPage();}
  else if(action==='check-email')go('check-email');
  else if(action==='continue-verified')continueVerified();
  else if(action==='check-verification'){await refresh(false);if(state.user?.emailVerified)continueVerified();else{verificationMessage='Your email is not verified yet. Open the link in your inbox, then try again.';render();}}
  else if(['available','profile','openings','discover','account','settings','admin','finance','premium','engagements','help','privacy','guidelines','wallet'].includes(action))go(action);
  else if(action==='post'){await selectRole('employer');if(requireProfile(()=>go('edit-opening')))go('edit-opening');}
  else if(action==='edit-opening')go('edit-opening',id);
  else if(action==='view-person')go('person',id);
  else if(action==='view-opening')go('opening',id);
  else if(action==='record')go('record',id);
  else if(action==='match-accept')acceptMatch(id);
  else if(action==='match-decline')declineMatch(id);
  else if(action==='availability-toggle'){if(!state.worker)throw Error('Create a worker profile first.');await change('hiring/profiles/worker',{...state.worker,acceptingBookings:state.worker.acceptingBookings===false});render();toast(state.worker.acceptingBookings===false?'Availability paused.':'You are ready to receive work enquiries.');}
  else if(action==='save-interview')saveInterview(id);
  else if(action==='invite')invite(id);else if(action==='apply')apply(id);else if(action==='report')report(id,b.dataset.kind);else if(action==='support')report('support','support');
  else if(action==='clear-filters'){clearDiscoveryFilters();disclosures.set('discover//filters',false);discover();}
  else if(action==='refresh'){await refresh();render();}
  else if(action==='locate'){locationPoint=await locate();await refresh(false);sort='nearest';discover();toast('Location ready.');}
  else if(action==='clear-location'){locationPoint=null;radius='';sort='recent';await refresh(false);discover();}
  else if(action==='share-location'||action==='remove-location'){if(!state.worker)throw Error('Create a work profile first.');const p={...state.worker};if(action==='share-location')p.coordinates=await locate();else delete p.coordinates;await change('hiring/profiles/worker',p);render();toast(action==='share-location'?'Location shared.':'Location removed.');}
  else if(action==='opening-status'){const o=state.openings.find(o=>o.id===id);await change('hiring/openings/'+id,{action:'status',status:o.status==='Open'?'Closed':'Open',revision:o.revision});render();}
  else if(action==='eng-action'){const g=engagement(id),op=b.dataset.op;if(['cancel','complete','confirm'].includes(op))modal(op==='cancel'?'Cancel this engagement?':op==='complete'?'Mark your side complete?':'Confirm work details?',op==='confirm'?'Read the scope, pay and schedule. Your confirmation applies to version '+g.version+'.':op==='complete'?'The work becomes completed after both participants confirm.':'This closes the conversation and does not reverse any direct payment.',`${errorBox()}${btn('Go back','close')}${btn('Confirm','eng-final',true,`${pidAttr(id)} data-op="${op}" data-revision="${b.dataset.revision}" data-version="${b.dataset.version}"`)}`);else{await change('hiring/engagements/'+id+'/'+op,{revision:g.revision});render();}}
  else if(action==='eng-final'){await change('hiring/engagements/'+id+'/'+b.dataset.op,{revision:Number(b.dataset.revision),version:Number(b.dataset.version)});dialog.close();render();}
  else if(action==='terms')terms(id);
  else if(action==='job-length'){const f=document.querySelector('#terms-form'),start=f?.elements.start?.value;if(!start)throw Error('Choose the job start date first.');const end=D.jobEndDate(start,b.dataset.length);if(!end)throw Error('Choose a valid start date.');f.elements.completionDate.value=end;f.elements.completionDate.min=start;toast('Job end date: '+D.friendlyDate(end));}
  else if(action==='review'){const g=engagement(id);if(!g?.reviewEligibility?.allowed)throw Error(g?.reviewEligibility?.reason||'Reviews open after the agreed job end date.');modal('How was the work?','This review will be visible on this profile to other hirers.',`<form id="review-form" ${pidAttr(id)}>${select('rating','Rating',[[5,'5 - Excellent'],[4,'4 - Very good'],[3,'3 - Good'],[2,'2 - Fair'],[1,'1 - Poor']],5)}${textarea('text','Your experience','')}${errorBox()}<button type="submit" class="button primary">Post my review</button></form>`);}
  else if(action==='block'||action==='unblock'){if(!requireProfile(()=>report(id)))return;await change('hiring/blocks',{role,target:id,blocked:action==='block'});go('profile');toast(action==='block'?'Contact blocked.':'Contact unblocked.');}
  else if(action==='read-all'){await change('hiring/notifications',{});render();}
  else if(action==='record-payment'){const g=engagement(id);modal('Record a payment you have sent','This records your declaration and asks the worker to acknowledge receipt. It does not initiate payment.',`<form id="payment-form" ${pidAttr(id)} data-request="${crypto.randomUUID()}">${field('amount','Amount paid (₦)',g.terms?.pay||'','number','required min="1" max="1000000" step="0.01"')}${select('method','Method',[['bank_transfer','Direct bank transfer'],['cash','Cash']],g.terms?.paymentMethod||'bank_transfer')}${field('note','Note (no bank credentials)','','text','maxlength="300"')}${errorBox()}<button type="submit" class="button primary">Record payment sent</button></form>`);}
  else if(action==='payment-ack'){await change('hiring/payments/'+id,{engagementId:b.dataset.eng,status:b.dataset.status});render();}
  else if(action==='logout'){authTransition=true;authEpoch++;stateEpoch++;try{await api('auth/logout',{});adoptState({user:null,worker:null,employer:null,workers:[],employers:[],openings:[],engagements:[],reviews:[],blocks:[],notifications:[],payments:[],reports:[],workerMatches:[]});clearDiscoveryFilters();}finally{authTransition=false;}await refresh(false);go('home');toast('Signed out. Your profiles are saved to your account.');}
  else if(action==='verify-email'){const r=await api('auth/verification/request',{});verificationMessage=r.message;await refresh(false);if(page==='check-email')render();else go('check-email');toast(r.message);}
}catch(e){toast(e.message);if(e.status===409){await refresh(false);if(!dialog.open)render();}}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('input',event=>{const e=event.target;if(e.id==='discovery-search'){q=e.value;renderDiscovery();}if(e.name==='search-city'){city=e.value;renderDiscovery();}});
document.addEventListener('change',event=>{const e=event.target;if(e.form?.id==='terms-form'&&e.name==='start')e.form.elements.completionDate.min=e.value;if(e.name==='search-category')category=e.value;if(e.name==='search-rating')minimum=e.value;if(e.name==='search-sort')sort=e.value;if(e.name==='search-radius'){radius=e.value;if(radius&&!locationPoint)toast('Use my location for distance filters.');}if(e.name.startsWith('search-'))renderDiscovery();if(e.name==='type'&&e.form?.id==='opening-form'){document.querySelector('[data-work-fields="ongoing"]').hidden=e.value==='One-off task';document.querySelector('[data-work-fields="task"]').hidden=e.value!=='One-off task';}if(e.name==='openingId'&&e.form?.id==='invite-form'){const fields=e.form.querySelector('[data-booking-fields]');fields.hidden=!!e.value;fields.querySelectorAll('input,textarea').forEach(x=>x.disabled=!!e.value);}});
document.addEventListener('submit',async event=>{const f=event.target;event.preventDefault();if(f.dataset.submitting==='true')return;f.dataset.submitting='true';const fd=new FormData(f),d=Object.fromEntries(fd),submit=f.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{
  if(f.id==='auth-form'){if(authMode==='forgot'){const r=await api('auth/forgot',{email:d.email});const status=f.querySelector('#auth-status');status.hidden=false;status.textContent=r.message;return;}if(authMode==='register'&&(!D.isAdult(d.dateOfBirth)||!fd.has('adultConsent')))throw Error('You must be 18 or older. Enter your real date of birth and confirm your age.');if(authMode==='register'&&!fd.has('termsConsent'))throw Error('Agree to the terms and privacy notice first.');authTransition=true;authEpoch++;stateEpoch++;let r;try{r=await api('auth/'+authMode,{...d,role:'both',activeRole:role,adultConsent:fd.has('adultConsent'),termsConsent:fd.has('termsConsent')});adoptState(r,authMode==='login'&&!pending);if(pending&&state.user.activeRole!==role){await api('wallet/role',{role});state.user.activeRole=role;}clearDiscoveryFilters();}finally{authTransition=false;}dialog.close();const next=pending;pending=null;if(state.verificationRequired){verificationNext=next;verificationMessage=r.verificationEmail?.message||'Open your verification email or request a new one below.';go('check-email');}else if(next)next();else go('profile');toast(authMode==='register'?'Account created.':'Signed in.');}
  else if(f.id==='premium-purchase-form'){const identity=authEpoch,r=await api('payments/premium/checkout',{requestId:f.dataset.request,tier:f.dataset.tier,amount:Number(f.dataset.amount),consent:fd.has('consent'),alertsConsent:fd.has('alertsConsent')});if(identity!==authEpoch)return;if(!checkoutRedirect(r)){await refresh(false);dialog.close();go('premium');}}
  else if(f.id==='job-alerts-form'){await api('payments/premium/alerts',{city:d.city,area:d.area,category:d.category,enabled:fd.has('enabled')});await refresh(false);render();toast('Job alert preferences saved.');}
  else if(f.id==='profile-form'){const p={...own(),...d,years:Number(d.years||0),pay:Number(d.pay||0)};if(role==='worker'){p.skills=D.list(d.skills);p.coverage=D.list(d.coverage);p.types=fd.getAll('types');p.days=fd.getAll('days');for(const k of ['travel','flexible','published','acceptingBookings','promoteProfile'])p[k]=fd.has(k);}else p.candidateAlerts=fd.has('candidateAlerts');await change('hiring/profiles/'+role,p);go('profile');lastHeartbeat=0;heartbeat();toast('Profile saved.');}
  else if(f.id==='opening-form'){const o={...d,requestId:f.dataset.request,min:Number(d.min||0),max:Number(d.max||0),years:Number(d.years||0),quote:fd.has('quote'),skills:D.list(d.skills),days:fd.getAll('days')};if(o.type==='One-off task')o.start=o.date;const previous=state.openings.find(o=>o.id===f.dataset.id);if(previous)o.revision=previous.revision;await change('hiring/openings'+(f.dataset.id?'/'+f.dataset.id:''),o);go('openings');toast('Opening saved.');}
  else if(f.id==='invite-form'){const body={role:'employer',workerId:f.dataset.worker,openingId:d.openingId,message:d.message,requestId:f.dataset.request};if(!d.openingId)body.booking={description:d.description,date:d.date,start:d.date,duration:d.duration,city:d.city,area:d.area};await change('hiring/engagements',body);dialog.close();go('engagements');toast('Invitation sent.');}
  else if(f.id==='interview-form'){await change('hiring/matches/'+f.dataset.id+'/accept',{interview:d,shareDetails:fd.has('shareDetails')});const g=state.engagements.find(g=>g.id===f.dataset.engagement);dialog.close();go(g?'record':'engagements',g?.id||'');toast('Interview invitation saved and queued for email.');}
  else if(f.id==='match-decline-form'){await change('hiring/matches/'+f.dataset.id+'/decline',{});dialog.close();go('available');toast('Profile declined for this opening.');}
  else if(f.id==='apply-form'){await change('hiring/engagements',{role:'worker',openingId:f.dataset.opening,message:d.message});dialog.close();go('engagements');toast('Your interest was sent.');}
  else if(['message-form','terms-form','review-form'].includes(f.id)){const g=engagement(f.dataset.id),op=f.id==='message-form'?'message':f.id==='terms-form'?'terms':'review';await change('hiring/engagements/'+g.id+'/'+op,{...d,terms:op==='terms'?d:undefined,rating:d.rating?Number(d.rating):undefined,revision:op==='terms'?Number(f.dataset.revision):g.revision});if(dialog.open)dialog.close();render();toast(op==='message'?'Message sent.':op==='terms'?'Work details proposed.':'Review published.');}
  else if(f.id==='report-form'){const r=await api('hiring/reports',{target:f.dataset.id,kind:f.dataset.kind,reason:d.reason,details:d.details});await refresh(false);dialog.close();toast(r.message+' Reference '+r.reference);}
  else if(f.id==='payment-form'){await change('hiring/payments',{engagementId:f.dataset.id,requestId:f.dataset.request,amount:Math.round(Number(d.amount)*100),method:d.method,note:d.note});dialog.close();render();toast('Payment reported. Waiting for acknowledgement.');}
  else if(f.id==='email-preferences-form'){await api('auth/email-preferences',{enabled:fd.has('enabled')});await refresh(false);render();toast('Email preference saved.');}
  else if(f.id==='password-form'){if(d.password!==d.confirmPassword)throw Error('The new passwords do not match.');const r=await api('auth/password',{currentPassword:d.currentPassword,password:d.password});await refresh(false);go('account');toast(r.message);}
  else if(f.id==='reset-form'||f.id==='verify-form'){const reset=f.id==='reset-form';if(reset&&d.password!==d.confirmPassword)throw Error('The new passwords do not match.');const r=await api(reset?'auth/reset':'auth/verify',{password:d.password,token:routeId});verifiedLinkUser=r.verifiedUserId||'';history.replaceState(null,'',reset?'#account':'#email-verified');page=reset?'account':'email-verified';routeId='';await refresh(false);render();toast(r.message);if(reset)auth('login');}
  else if(f.id==='admin-lock-form'){if(!fd.has('confirm'))throw Error('Confirm you have checked this account first.');const days=Number(d.days);if(d.action==='temporary'&&(!Number.isInteger(days)||days<1||days>365))throw Error('Choose between 1 and 365 days.');await api('admin/account-lock',{userId:f.dataset.id,action:d.action,reason:d.reason,untilAt:d.action==='temporary'?new Date(Date.now()+days*86400000).toISOString():null});dialog.close();await adminPage();toast('Account access updated.');}
  else if(f.id==='admin-users-form'){adminQuery=String(d.q||'').trim();adminVerified=d.verified||'';adminListPage=1;await adminPage();}
  else if(f.classList.contains('admin-report-form')){await api('admin/reports',{...d,id:f.dataset.id});await refresh(false);adminPage();toast('Resolution saved.');}
}catch(e){formError(e.message);if(e.status===409)await refresh(false);}finally{delete f.dataset.submitting;if(submit?.isConnected)submit.disabled=false;}});
window.addEventListener('lochire-theme-change',()=>{if(page==='settings')render();});
document.addEventListener('toggle',event=>{const d=event.target;if(d.matches?.('main [data-disclosure]'))disclosures.set(page+'/'+routeId+'/'+d.dataset.disclosure,d.open);},true);
document.addEventListener('invalid',event=>{let el=event.target.parentElement;while(el){if(el.tagName==='DETAILS')el.open=true;el=el.parentElement;}},true);
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
async function heartbeat(){if(!state.user||role!=='worker'||!state.worker?.published||document.hidden||Date.now()-lastHeartbeat<40000)return;lastHeartbeat=Date.now();try{await api('hiring/presence',{});}catch{lastHeartbeat=0;}}
setInterval(heartbeat,45000);
function hashRoute(){const [p,...parts]=location.hash.slice(1).split('/');page=p||(location.pathname.replace(/\/$/,'')==='/admin'?'admin':'home');try{routeId=decodeURIComponent(parts.join('/'));}catch{routeId='';}render();}
window.addEventListener('hashchange',hashRoute);window.addEventListener('focus',()=>refresh());document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});window.addEventListener('pagehide',()=>{locationPoint=null;});setInterval(()=>{if(!document.hidden&&!dialog.open&&(!main.querySelector('form')||page==='record'))refresh();},30000);
async function boot(){const epoch=stateEpoch;const results=await Promise.allSettled([api('config'),api(statePath())]);if(results[0].status==='fulfilled')config=results[0].value;if(results[1].status==='fulfilled'){if(epoch===stateEpoch)adoptState(results[1].value,true);}else networkError='LocHire could not connect. '+results[1].reason.message;loading=false;hashRoute();heartbeat();const premiumRef=new URL(location.href).searchParams.get('premium_reference');if(premiumRef&&/^LHPR-[a-f0-9]{32}$/.test(premiumRef)){if(state.user){try{await checkPremium(premiumRef);history.replaceState(null,'',location.pathname+'#premium');}catch(e){go('premium');toast(e.message+' Your purchase is saved; use Check payment to retry.');}}else{pending=()=>location.reload();auth();}return;}}
hashRoute();boot();
})();
